  const advice = [
    "Point llm-pi-ai providers.*.baseURL at a suggestedBaseURL below (keep the /v1 suffix).",
    "If only the Windows host IP works: set OLLAMA_HOST=0.0.0.0:11434 (or the app's 'listen on all interfaces') then re-probe.",
